package com.cekalix.controlador;
import com.cekalix.dao.UsuarioDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/login")
public class LoginServlet extends HttpServlet {private final UsuarioDAO dao=new UsuarioDAO();
protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/vistas/login.jsp").forward(q,p);}
protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");String u=q.getParameter("usuario"),k=q.getParameter("clave");try{var r=dao.autenticar(u==null?"":u.trim(),k==null?"":k);if(r.isPresent()){q.getSession(true).setAttribute("usuarioSesion",r.get());p.sendRedirect(q.getContextPath()+"/inicio");}else{q.setAttribute("error","Usuario o contraseña incorrectos.");doGet(q,p);}}catch(SQLException e){q.setAttribute("error","No se pudo conectar con MySQL. Verifica la base de datos y las credenciales.");doGet(q,p);}}}